impl protobuf::ParseResult {
    /// The nodes of every statement, as pg_query walks them.
    pub fn nodes(&self) -> Vec<(NodeRef<'_>, i32, Context, bool)> {
        self.stmts.iter().filter_map(|s| s.stmt.as_ref().and_then(|s| s.node.as_ref()).map(|n| n.nodes())).flatten().collect()
    }
}
